    for batch in range(9):
        add('writer-inspect-before-batch-%d' % batch, 30, False, 'writer-running', 8)
        add('batch-%d' % batch, 48, True, 'writer-running', 8)
    add('writer-inspect-before-stop', 30, False, 'writer-running', 8)
