                view=view[count:]
            io.sync(fd);after=C.nine(io.fstat(fd))
            if after!=C.nine(io.lstat(str(path))) or int(after['size'])!=start+length:
                raise ValueError('SOURCE_WRITE_SIZE_PATH_NINE')
            complete=start+length==expected['bytes'];seen=None;sha=None
            if complete:
