                # first byte, including a later EOF/hash/deadline failure.
                ledger.admit(namespace+str(path),after,expected['sha256'],expected['bytes'],'NEW_LINUX_COPY_FULL_EOF')
                io.seek(fd,0);h=hashlib.sha256();seen=0
