        try:
            self.cohort.open_all(); self.bodies=self.cohort.read_all()
            for entry in self.cohort.owned:
                if max(int(entry['pin']['mtime_ns']),int(entry['pin']['ctime_ns']))>int(manifest['sourceStoppedUnixNs']):
                    raise ValueError('LATE_SOURCE_AFTER_STOP')
            self.by_name={row['name']:row for row in rows}
            specs=manifest['lateSourceInputSpecs']
            if len(late_rows)!=len(specs) or {r['name'] for r in late_rows}!={r['name'] for r in specs}:
                raise ValueError('COMPLETE_LATE_SOURCE_DATA_SET')
            for row in late_rows:
                spec=next(s for s in specs if s['name']==row['name'])
                if row['path']!=spec['path'] or type(row['bytes']) is not int or not 0<=row['bytes']<=spec['maximumBytes']:
                    raise ValueError('LATE_SOURCE_DATA_PATH_CAP')
                C.valid_nine(row['PRE9'])
            self.late=C.Cohort([dict(r,expectedNine=r['PRE9'],kind='ROOT_LATE_SOURCE_ENABLING_DATA') for r in late_rows],ledger,owner=(501,20),fs=source_fs)
            self.late.open_all(); self.bodies.update(self.late.read_all())
            self.by_name.update({r['name']:r for r in late_rows})
        except BaseException as failure:
            error=failure
        if error is not None:
            check=self.close(error)
            raise C.SourceFailure(check['closeErrors']) from error

    def check(self):
        if self.closed: raise ValueError('SOURCE_LEASE_ALREADY_CLOSED')
        for entry in self.cohort.owned:
            if entry['fd'] is None or C.nine(self.cohort.fs.fstat(entry['fd']))!=entry['pin'] or C.nine(self.cohort.fs.lstat(entry['row']['path']))!=entry['pin']:
                raise ValueError('CURRENT_HELD_ROOT_MAC_SOURCE_NINE')
        if self.late is not None:
            for entry in self.late.owned:
                if entry['fd'] is None or C.nine(self.late.fs.fstat(entry['fd']))!=entry['pin'] or C.nine(self.late.fs.lstat(entry['row']['path']))!=entry['pin']:
                    raise ValueError('CURRENT_HELD_ROOT_LATE_SOURCE_DATA_NINE')

    def raw(self,name):
        self.check(); return self.bodies[self.by_name[name]['path']]

    def module(self,name,dependencies):
        if name in self.modules: raise ValueError('NO_LIVE_MODULE_REPLACEMENT_OR_CACHE_FALLBACK')
        row=self.by_name[name]; module=types.ModuleType('held_'+name); module.__file__=row['path']
        module.__dict__.update(dependencies)
        exec(compile(self.raw(name),row['path'],'exec',dont_inherit=True),module.__dict__)
        self.modules[name]=module
        self.check(); return module

    def close(self,primary=None):
        if self.closed: raise ValueError('SOURCE_LEASE_CLOSE_RETRY_FORBIDDEN')
        self.closed=True
        late=None;main=None;failures=[]
        if self.late is not None:
            try:late=self.late.final_and_close(primary)
            except BaseException as error:failures.append(repr(error))
        try:main=self.cohort.final_and_close(primary)
        except BaseException as error:failures.append(repr(error))
        if main is None:main={'closeErrors':[],'sourceEligibility':False,'runtimeAuthority':False}
        main['closeErrors']+=failures
        if late is not None:
            main['lateDataClose']=late; main['closeErrors']+=late['closeErrors']
        return main


def run(manifest,manifest_sha256,approval_sha256,release,ledger,directory,late_rows,source_fs=None):
    """The caller owns qualified header custody; this function owns all sources."""
    lease=None; primary=None; result=None; closed=None
    try:
        lease=Lease(manifest,manifest_sha256,approval_sha256,ledger,late_rows,source_fs=source_fs)
        T=lease.module('T',{'C':C}); S=lease.module('S',{'C':C,'T':T})
        L=lease.module('L',{'C':C})
        common_row=lease.by_name['M']; common_entry=next(e for e in lease.cohort.owned if e['row']['name']=='M')
        anchor={'bootstrap':lease.raw('A').decode(),'fd':common_entry['fd'],
            'row':{'path':common_row['path'],'PRE9':common_entry['pin'],'bytes':common_row['bytes'],'sha256':common_row['sha256']}}
        M=lease.module('M',{'SOURCE_ANCHOR':anchor})
        D=lease.module('D',{'C':C,'T':T,'S':S,'L':L,'M':M})
        carry=C.strict(lease.raw('carry')); wire=C.strict(lease.raw('wire')); proof=C.strict(lease.raw('proof'))
        if proof['carrySha256']!=C.digest(lease.raw('carry')) or wire['macCarrySha256']!=C.digest(lease.raw('carry')):
            raise ValueError('EXACT_CARRY_WIRE_ORIGINAL113_PROOF_DIGEST')
        result=D.execute(release,lease,ledger,carry,wire,proof,
            {'C':lease.raw('C'),'Q':lease.raw('Q'),'B':lease.raw('B'),'carry':lease.raw('carry'),'wire':lease.raw('wire')},directory,C.strict(lease.raw('sender')))
    except BaseException as error:
        primary=error
    finally:
        if lease is not None: closed=lease.close(primary)
    if primary is not None or (closed is not None and closed['closeErrors']):
        raise C.SourceFailure(([repr(primary)] if primary else [])+(closed['closeErrors'] if closed else [])) from primary
    result['rootSourceLeaseClose']=closed
    result['sourceEligibility']=False; result['runtimeAuthority']=False
    return result

"""Finite capture; native-identity session anchor reconciles owned descendants.
The anchor cannot exit normally before release, so its group cannot be reused.
Unknown ownership is sticky and never permits a foreign signal or dispatch.
"""
import ctypes
import datetime
import hashlib
import json
import os
from pathlib import Path
import select
import selectors
import signal
import socket
import subprocess
import sys
import time

PIPE_LIMIT = 262144
INPUT_LIMIT = 327692
CONTROL_LIMIT = 8192

class OwnedGroupResidual(RuntimeError):
    pass

class OwnedGroupUnknown(RuntimeError):
    pass

def digest(path):
    return hashlib.sha256(Path(path).read_bytes()).hexdigest()

def durable(path, raw):
    path = Path(path)
    fd = os.open(path, os.O_WRONLY | os.O_CREAT | os.O_EXCL | os.O_NOFOLLOW, 0o600)
    try:
        data = memoryview(raw)
        while data:
            count = os.write(fd, data)
            if count <= 0:
                raise OSError('coordinator_write_failure')
            data = data[count:]
        os.fsync(fd)
    finally:
        os.close(fd)
    directory = os.open(path.parent, os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW)
    try:
        os.fsync(directory)
    finally:
        os.close(directory)

def durable_json(path, value):
    durable(path, (json.dumps(value, indent=2) + '\n').encode())

def native_identity(pid):
    if sys.platform == 'linux':
        raw = Path('/proc/' + str(pid) + '/stat').read_text()
        fields = raw[raw.rindex(')') + 2:].split()
        return {'pid': pid, 'birthTicks': fields[19], 'group': int(fields[2]),
                'session': int(fields[3]), 'platform': 'linux-proc-stat'}
    if sys.platform == 'darwin':
        class BSDInfo(ctypes.Structure):
            _fields_ = [(n, ctypes.c_uint32) for n in ('flags','status','xstatus','pid','ppid','uid','gid','ruid','rgid','svuid','svgid','rfu1')]
            _fields_ += [('comm', ctypes.c_char * 16), ('name', ctypes.c_char * 32)]
            _fields_ += [(n, ctypes.c_uint32) for n in ('nfiles','pgid','pjobc','e_tdev','e_tpgid','nice')]
            _fields_ += [('start_sec', ctypes.c_uint64), ('start_usec', ctypes.c_uint64)]
        info = BSDInfo()
        lib = ctypes.CDLL('/usr/lib/libproc.dylib', use_errno=True)
        lib.proc_pidinfo.argtypes = [ctypes.c_int,ctypes.c_int,ctypes.c_uint64,ctypes.c_void_p,ctypes.c_int]
        lib.proc_pidinfo.restype = ctypes.c_int
        if lib.proc_pidinfo(pid, 3, 0, ctypes.byref(info), ctypes.sizeof(info)) != ctypes.sizeof(info) or info.pid != pid:
            raise OwnedGroupUnknown('native_anchor_identity_unavailable')
        return {'pid':pid,'birthSeconds':str(info.start_sec),'birthMicroseconds':str(info.start_usec),
                'group':info.pgid,'session':os.getsid(pid),'uid':info.uid,'platform':'darwin-proc-pidinfo-bsdinfo'}
    raise OwnedGroupUnknown('native_group_observation_unsupported')

def group_members(group):
    if sys.platform == 'linux':
        members = []
        for entry in Path('/proc').iterdir():
            if not entry.name.isdecimal():
                continue
            try:
                raw = (entry/'stat').read_bytes()
            except (FileNotFoundError,ProcessLookupError):
                continue
            if len(raw) > 4096:
                raise OwnedGroupUnknown('native_proc_stat_bound')
            fields = raw[raw.rindex(b')')+2:].split()
            if int(fields[2]) == group:
                members.append({'pid':int(entry.name),'state':fields[0].decode('ascii')})
        return sorted(members,key=lambda r:r['pid'])
    result = subprocess.run(['/bin/ps','-axo','pid=,pgid=,stat='],capture_output=True,timeout=1,env={'PATH':'/usr/bin:/bin'},start_new_session=True)
    if result.returncode != 0 or len(result.stdout) > PIPE_LIMIT or result.stderr:
        raise OwnedGroupUnknown('native_group_observation_failed')
    members = []
    for line in result.stdout.splitlines():
        fields = line.split()
        if len(fields) != 3:
            raise OwnedGroupUnknown('native_group_observation_malformed')
        if int(fields[1]) == group:
            members.append({'pid':int(fields[0]),'state':fields[2].decode('ascii')})
    return sorted(members,key=lambda r:r['pid'])

def anchor_matches(process, identity):
    return process.poll() is None and native_identity(process.pid) == identity and os.getpgid(process.pid) == os.getsid(process.pid) == process.pid

def send(control, value):
    raw = (json.dumps(value,separators=(',',':')) + '\n').encode()
    if len(raw) > CONTROL_LIMIT:
        raise OwnedGroupUnknown('bounded_anchor_control_required')
    control.sendall(raw)

def control_readable(control, wait):
    with selectors.DefaultSelector() as readiness:
        readiness.register(control, selectors.EVENT_READ)
        return bool(readiness.select(wait))

def anchor_main(fd, argv):
    control = socket.socket(fileno=fd)
    own = os.getpid()
    identity = native_identity(own)
    assert os.getpgid(0) == os.getsid(0) == own
    if sys.platform == 'linux':
        libc = ctypes.CDLL(None,use_errno=True)
        if libc.prctl(36,1,0,0,0) != 0:  # PR_SET_CHILD_SUBREAPER
            raise OwnedGroupUnknown('owned_descendant_reaping_unavailable')
    send(control,{'event':'ready','identity':identity})
    buffered = bytearray()
    total = 0
    command = None
    exit_sent = False
    until = time.monotonic() + 205
    def report_exit():
        nonlocal exit_sent
        if command is not None and not exit_sent and command.poll() is not None:
            send(control,{'event':'command-exit','returnCode':command.returncode})
            exit_sent = True
    while time.monotonic() < until:
        report_exit()
        if not control_readable(control,0.02):
            continue
        raw = control.recv(CONTROL_LIMIT+1)
        if not raw:
            raise OwnedGroupUnknown('anchor_controller_disappeared')
        total += len(raw)
        buffered.extend(raw)
        if total > CONTROL_LIMIT:
            raise OwnedGroupUnknown('anchor_control_overflow')
        while b'\n' in buffered:
            frame,_,tail = buffered.partition(b'\n')
            buffered = bytearray(tail)
            event = json.loads(frame)
            if event == {'event':'start'} and command is None:
                try:
                    command = subprocess.Popen(argv,stdin=0,stdout=1,stderr=2)
                    send(control,{'event':'command-start','pid':command.pid})
                except BaseException as error:
                    send(control,{'event':'spawn-failure','failureClass':type(error).__name__})
                for stream_fd in (0,1,2):
                    os.close(stream_fd)
            elif event == {'event':'reconcile'}:
                before = group_members(own)
                deadline = time.monotonic()+8
                signals = []
                while True:
                    report_exit()
                    assert native_identity(own) == identity
                    members = [r for r in group_members(own) if r['pid'] != own]
                    if not members:
                        break
                    for member in members:
                        if 'Z' in member['state']:
                            continue  # Reap before querying a dead member's native identity.
                        pid = member['pid']
                        try:
                            pin = native_identity(pid)
                            if pin['group'] != own or pin['session'] != own or native_identity(pid) != pin:
                                raise OwnedGroupUnknown('owned_member_identity_drift')
                            os.kill(pid,signal.SIGKILL)
                            signals.append({'pid':pid,'identity':pin,'signal':'SIGKILL'})
                        except (ProcessLookupError,FileNotFoundError):
                            pass
                    report_exit()
                    if sys.platform == 'linux':
                        while True:
                            try:
                                pid,status = os.waitpid(-1,os.WNOHANG)
                                if pid == 0:
                                    break
                                if command is not None and pid == command.pid:
                                    command.returncode = os.waitstatus_to_exitcode(status)
                            except ChildProcessError:
                                break
                        report_exit()
                    if time.monotonic() >= deadline:
                        raise OwnedGroupUnknown('owned_group_reconciliation_deadline')
                    time.sleep(0.02)
                send(control,{'event':'reconciled','before':before,'signals':signals,'final':group_members(own)})
            elif event == {'event':'release'}:
                assert native_identity(own) == identity and [r['pid'] for r in group_members(own)] == [own]
                control.close()
                return
            else:
                raise OwnedGroupUnknown('unexpected_anchor_control')
    raise OwnedGroupUnknown('finite_anchor_deadline')

def run(label, argv, output_directory, timeout, env, input_bytes=None, progress=None, required=True):
    if not label or any(c not in 'abcdefghijklmnopqrstuvwxyz0123456789-' for c in label):
        raise ValueError('fixed_receipt_label_required')
    if not 0 < timeout <= 190:
        raise ValueError('finite_command_timeout_required')
    if input_bytes is not None and not 0 < len(input_bytes) <= INPUT_LIMIT:
        raise ValueError('finite_stdin_required')
